26	/// Camera block demo. Move a red circle inside a boundary rectangle with WASD/arrows;
27	/// switch between five fixed camera targets (numbered 1–5, each shown as a hoverable
28	/// region in the world) and a follow mode (key 0). The "smooth lerp" toggle controls
29	/// the damping on <see cref="CameraFollowTargetComponent"/>: when on, the camera eases
30	/// toward its target (ball in follow mode, or the corresponding zone center in fixed
31	/// modes); when off, it snaps instantly.
32	public class CameraDemoScreen : IGameScreen
33	{
34	    private const float BoundaryHalfWidth = 380f;
35	    private const float BoundaryHalfHeight = 220f;
36	    // Camera-movement bounds in follow mode — a little smaller than the boundary,
37	    // so the red dot can push past the camera's reach toward the screen edges.
38	    private const float CameraBoundsHalfWidth = 280f;
39	    private const float CameraBoundsHalfHeight = 140f;
40	    private const float ZoneSize = 80f;
41	    private const float BallRadius = 20f;
42	    private const float MoveSpeed = 240f;
43	
44	    private const float DampingSmooth = 5f;
45	    private const float DampingInstant = 100f;
46	
47	    /// Keyboard-key 0..5 maps directly to enum index: 0 Follow, 1 TL, 2 TR,
48	    /// 3 BR, 4 BL, 5 Center. Reordering is intentional — clockwise around the
49	    /// boundary corners with Center last.
50	    public enum Mode { Follow, FixedTL, FixedTR, FixedBR, FixedBL, FixedCenter }
51	
52	    private readonly ContentManager _content;
53	    private readonly GraphicsDevice _graphicsDevice;
54	    private readonly MonoDreams.Component.Camera _camera;
55	    private readonly ViewportManager _viewportManager;
56	    private readonly SpriteBatch _spriteBatch;
57	    private readonly World _world;
58	    private readonly Dictionary<RenderTargetID, RenderTarget2D> _renderTargets;
59	    private readonly BitmapFont _font;
60	
61	    private ScreenController? _screenController;
62	    private Entity _ball;
63	    private Entity _cameraAnchor;
64	    private Entity _lerpToggle;
65	    private Entity _targetCross;
66	    private Entity _cameraBoundsRect;
67	    private Mode _mode = Mode.Follow;
68	    private bool _lerpSmooth = true;
69	
70	    private readonly Dictionary<Mode, Entity> _sidebarButtons = new();
71	    private readonly Dictionary<Mode, Entity> _worldZoneButtons = new();
72	
73	    public ISystem<GameState> UpdateSystem { get; }
74	    public ISystem<GameState> DrawSystem { get; }
