78	        ViewportManager viewportManager, SpriteBatch spriteBatch)
79	    {
80	        _graphicsDevice = graphicsDevice;
81	        _content = content;
82	        _camera = camera;
83	        _viewportManager = viewportManager;
84	        _spriteBatch = spriteBatch;
85	        _renderTargets = new Dictionary<RenderTargetID, RenderTarget2D>
86	        {
87	            { RenderTargetID.Main, new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight) },
88	            { RenderTargetID.UI, new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight) },
89	            { RenderTargetID.HUD, new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight) },
90	        };
91	        _font = content.Load<BitmapFont>("Fonts/UAV-OSD-Sans-Mono-72-White-fnt");
92	
93	        camera.Position = Vector2.Zero;
94	
95	        _world = new World();
96	        UpdateSystem = CreateUpdateSystem();
97	        DrawSystem = CreateDrawSystem();
