100	    public void Load(ScreenController screenController, ContentManager content)
101	    {
102	        _screenController = screenController;
103	        _world.Subscribe<DemoButtonClicked>(OnButtonClicked);
104	
105	        var cursorTextures = new Dictionary<CursorType, Texture2D>
106	        {
107	            [CursorType.Default] = content.Load<Texture2D>("Cursor/default"),
108	            [CursorType.Pointer] = content.Load<Texture2D>("Cursor/pointer"),
109	            [CursorType.Hand] = content.Load<Texture2D>("Cursor/hand"),
110	        };
111	        MonoDreams.Cursor.Cursor.Create(_world, cursorTextures, RenderTargetID.HUD);
112	
113	        _cameraAnchor = _world.CreateEntity();
114	        _cameraAnchor.Set(new TransformComponent(Vector2.Zero));
115	
116	        CreateBoundary();
117	        CreateCameraBoundsRect();
118	        CreateWorldZones();
119	        CreateBall();
120	        CreateTargetCross();
121	        CreateCameraCenterCross();
122	        BuildHud(content);
123	
124	        SetMode(_mode);
125	    }
