127	    // ─── public bridges for the keyboard system ───────────────────────────────
128	
129	    public void SetMode(Mode mode)
130	    {
131	        _mode = mode;
132	        foreach (var (m, btn) in _sidebarButtons) UpdateActive(btn, m == mode);
133	        foreach (var (m, btn) in _worldZoneButtons) UpdateActive(btn, m == mode);
134	
135	        // The dashed camera-bounds guide only makes sense while the camera tracks
136	        // the red dot — show it in follow mode, hide it in the fixed modes.
137	        SetCameraBoundsVisible(mode == Mode.Follow);
138	
139	        if (mode == Mode.Follow)
140	        {
141	            if (_cameraAnchor.Has<CameraFollowTargetComponent>())
142	                _cameraAnchor.Remove<CameraFollowTargetComponent>();
143	            if (!_ball.Has<CameraFollowTargetComponent>())
144	                _ball.Set(new CameraFollowTargetComponent());
145	            ApplyDampingTo(_ball);
146	            _ball.Get<CameraFollowTargetComponent>().Bounds = CameraBounds();
147	            ReparentTargetCross(_ball);
148	        }
149	        else
150	        {
151	            if (_ball.Has<CameraFollowTargetComponent>())
152	                _ball.Remove<CameraFollowTargetComponent>();
153	            var anchorTransform = _cameraAnchor.Get<TransformComponent>();
154	            anchorTransform.Position = ModeCameraTarget(mode);
155	            if (!_cameraAnchor.Has<CameraFollowTargetComponent>())
156	                _cameraAnchor.Set(new CameraFollowTargetComponent());
157	            ApplyDampingTo(_cameraAnchor);
158	            ReparentTargetCross(_cameraAnchor);
159	
160	            if (!_lerpSmooth) _camera.Position = anchorTransform.Position;
161	        }
162	    }
163	
164	    private void ReparentTargetCross(Entity newParent)
165	    {
166	        if (!_targetCross.IsAlive) return;
167	        // SetParent overwrites ChildOfComponent + transform.Parent in place;
168	        // we deliberately skip RemoveParent so the cross's LOCAL position stays
169	        // at (0,0). RemoveParent snapshots the current world position into the
170	        // local one, which would double the offset on the next reparent.
171	        _targetCross.SetParent(newParent);
172	        _targetCross.Get<TransformComponent>().Position = Vector2.Zero;
173	    }
174	
175	    public void GoBackToLauncher() => _screenController?.LoadScreen(DemoScreens.Launcher);
176	
177	    public void ToggleLerp()
178	    {
179	        if (!_lerpToggle.IsAlive || !_lerpToggle.Has<ToggleSwitchComponent>()) return;
180	        var sw = _lerpToggle.Get<ToggleSwitchComponent>();
181	        sw.On = !sw.On;
182	        _lerpSmooth = sw.On;
183	        _lerpToggle.Set(sw);
184	
185	        if (_ball.Has<CameraFollowTargetComponent>()) ApplyDampingTo(_ball);
186	        if (_cameraAnchor.Has<CameraFollowTargetComponent>())
187	        {
188	            ApplyDampingTo(_cameraAnchor);
189	            if (!_lerpSmooth) _camera.Position = _cameraAnchor.Get<TransformComponent>().Position;
190	        }
191	    }
192	
193	    private void ApplyDampingTo(Entity target)
194	    {
195	        if (!target.Has<CameraFollowTargetComponent>()) return;
196	        var ft = target.Get<CameraFollowTargetComponent>();
197	        ft.DampingX = _lerpSmooth ? DampingSmooth : DampingInstant;
198	        ft.DampingY = _lerpSmooth ? DampingSmooth : DampingInstant;
199	        ft.MaxDistanceX = 10000f;
200	        ft.MaxDistanceY = 10000f;
201	    }
202	
203	    private static void UpdateActive(Entity entity, bool active)
204	    {
205	        if (!entity.IsAlive || !entity.Has<DemoButtonComponent>()) return;
206	        ref var b = ref entity.Get<DemoButtonComponent>();
207	        b.IsActive = active;
208	    }
