210	    // Camera centers exactly on the zone the user clicked. Zone centers sit at the
211	    // corners offset by half the zone size so the zone sprite is fully on-screen.
212	    private static Vector2 ModeCameraTarget(Mode m)
213	    {
214	        var halfZone = ZoneSize / 2f;
215	        return m switch
216	        {
217	            Mode.FixedTL     => new Vector2(-BoundaryHalfWidth + halfZone, -BoundaryHalfHeight + halfZone),
218	            Mode.FixedTR     => new Vector2( BoundaryHalfWidth - halfZone, -BoundaryHalfHeight + halfZone),
219	            Mode.FixedCenter => Vector2.Zero,
220	            Mode.FixedBL     => new Vector2(-BoundaryHalfWidth + halfZone,  BoundaryHalfHeight - halfZone),
221	            Mode.FixedBR     => new Vector2( BoundaryHalfWidth - halfZone,  BoundaryHalfHeight - halfZone),
222	            _                => Vector2.Zero,
223	        };
224	    }
225	
226	    private static Vector2 ZoneTopLeft(Mode m)
227	    {
228	        var half = ZoneSize / 2f;
229	        return m switch
230	        {
231	            Mode.FixedTL     => new Vector2(-BoundaryHalfWidth,             -BoundaryHalfHeight),
232	            Mode.FixedTR     => new Vector2( BoundaryHalfWidth - ZoneSize,  -BoundaryHalfHeight),
233	            Mode.FixedCenter => new Vector2(-half, -half),
234	            Mode.FixedBL     => new Vector2(-BoundaryHalfWidth,              BoundaryHalfHeight - ZoneSize),
235	            Mode.FixedBR     => new Vector2( BoundaryHalfWidth - ZoneSize,   BoundaryHalfHeight - ZoneSize),
236	            _ => Vector2.Zero,
237	        };
238	    }
