240	    // ─── button click routing ────────────────────────────────────────────────
241	
242	    private void OnButtonClicked(in DemoButtonClicked msg)
243	    {
244	        switch (msg.Id)
245	        {
246	            case DemoHeader.BackId: _screenController?.LoadScreen(DemoScreens.Launcher); break;
247	            case DemoHeader.ExitId: _screenController?.Game.Exit(); break;
248	            case "mode.follow": SetMode(Mode.Follow); break;
249	            case "mode.tl":     SetMode(Mode.FixedTL); break;
250	            case "mode.tr":     SetMode(Mode.FixedTR); break;
251	            case "mode.center": SetMode(Mode.FixedCenter); break;
252	            case "mode.bl":     SetMode(Mode.FixedBL); break;
253	            case "mode.br":     SetMode(Mode.FixedBR); break;
254	            case "toggle.lerp": ToggleLerp(); break;
255	        }
256	    }
