260	    private void CreateBoundary()
261	    {
262	        var bounds = new Rectangle(
263	            -(int)BoundaryHalfWidth, -(int)BoundaryHalfHeight,
264	            (int)BoundaryHalfWidth * 2, (int)BoundaryHalfHeight * 2);
265	
266	        var boundary = _world.CreateEntity();
267	        boundary.Set(new TransformComponent(Vector2.Zero));
268	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.2f };
269	        draw.SetMeshData(new RectangleOutlineMeshGenerator(bounds, thickness: 2f, color: SproutPalette.TextLight));
270	        boundary.Set(draw);
271	        boundary.Set<VisibleComponent>();
272	    }
273	
274	    /// World-space rectangle the camera position is clamped to in follow mode.
275	    private static Rectangle CameraBounds() => new(
276	        -(int)CameraBoundsHalfWidth, -(int)CameraBoundsHalfHeight,
277	        (int)CameraBoundsHalfWidth * 2, (int)CameraBoundsHalfHeight * 2);
278	
279	    /// Soft-yellow dashed guide showing how far the camera can travel in follow
280	    /// mode. Created once; its visibility is toggled by <see cref="SetMode"/> so it
281	    /// only appears while the red dot is the camera target.
282	    private void CreateCameraBoundsRect()
283	    {
284	        _cameraBoundsRect = _world.CreateEntity();
285	        _cameraBoundsRect.Set(new TransformComponent(Vector2.Zero));
286	        // 0.25 sits just above the solid boundary outline (0.2) and below the
287	        // world-zone outlines, ball, and crosses.
288	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.25f };
289	        draw.SetMeshData(new DashedRectangleOutlineMeshGenerator(
290	            CameraBounds(), thickness: 2f, color: SproutPalette.SoftYellow, dashLength: 14f, gapLength: 9f));
291	        _cameraBoundsRect.Set(draw);
292	        // VisibleComponent is added/removed by SetCameraBoundsVisible — no
293	        // CullingSystem runs in this demo, so the tag fully controls visibility.
294	    }
295	
296	    private void SetCameraBoundsVisible(bool visible)
297	    {
298	        if (!_cameraBoundsRect.IsAlive) return;
299	        if (visible && !_cameraBoundsRect.Has<VisibleComponent>())
300	            _cameraBoundsRect.Set<VisibleComponent>();
301	        else if (!visible && _cameraBoundsRect.Has<VisibleComponent>())
302	            _cameraBoundsRect.Remove<VisibleComponent>();
303	    }
