305	    private void CreateWorldZones()
306	    {
307	        // Numbering matches the keyboard digits — 1 TL, 2 TR, 3 BR, 4 BL, 5 Center.
308	        CreateWorldZone(Mode.FixedTL,     "1", "mode.tl");
309	        CreateWorldZone(Mode.FixedTR,     "2", "mode.tr");
310	        CreateWorldZone(Mode.FixedBR,     "3", "mode.br");
311	        CreateWorldZone(Mode.FixedBL,     "4", "mode.bl");
312	        CreateWorldZone(Mode.FixedCenter, "5", "mode.center");
313	    }
