315	    private void CreateWorldZone(Mode mode, string label, string id)
316	    {
317	        var topLeft = ZoneTopLeft(mode);
318	        var sharedTransform = new TransformComponent(topLeft);
319	
320	        var container = _world.CreateEntity();
321	        container.Set(sharedTransform);
322	
323	        const float labelScale = 0.50f;
324	        var measured = _font.MeasureString(label);
325	        var labelSize = new Vector2(measured.Width * labelScale, measured.Height * labelScale);
326	        var labelOffset = new Vector2((ZoneSize - labelSize.X) / 2f, (ZoneSize - labelSize.Y) / 2f);
327	        var labelEntity = _world.CreateEntity();
328	        labelEntity.Set(new TransformComponent(labelOffset));
329	        labelEntity.SetParent(container);
330	        labelEntity.Set(new DynamicTextComponent
331	        {
332	            Target = RenderTargetID.Main,
333	            LayerDepth = 0.35f,
334	            TextContent = label,
335	            Font = _font,
336	            Color = SproutPalette.TextLight,
337	            Scale = labelScale,
338	            IsRevealed = true,
339	            VisibleCharacterCount = int.MaxValue,
340	        });
341	        labelEntity.Set<VisibleComponent>();
342	
343	        var outline = _world.CreateEntity();
344	        outline.Set(sharedTransform);
345	        outline.Set(new SimpleButtonComponent
346	        {
347	            Size = new Vector2(ZoneSize, ZoneSize),
348	            LineThickness = 1.5f,
349	            Color = SproutPalette.TextLight,
350	            TextEntity = labelEntity,
351	            Target = RenderTargetID.Main,
352	        });
353	        outline.Set(new DemoButtonComponent
354	        {
355	            Id = id,
356	            DefaultColor = SproutPalette.TextLight,
357	            HoveredColor = SproutPalette.TextHover,
358	            ActiveColor = SproutPalette.TextSelected,
359	        });
360	        outline.Set<VisibleComponent>();
361	        _worldZoneButtons[mode] = outline;
362	    }
