364	    private void CreateBall()
365	    {
366	        _ball = _world.CreateEntity();
367	        _ball.Set(new TransformComponent(Vector2.Zero));
368	        _ball.Set(new PlayerBallTag());
369	        // 0.97 puts the ball above the world-zone button outlines (those get
370	        // LayerDepth=0.95 from ButtonMeshPrepSystem) so the ball doesn't get
371	        // clipped by a zone's outline as it crosses through.
372	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.97f };
373	        draw.SetMeshData(new CircleMeshGenerator(Vector2.Zero, BallRadius, SproutPalette.Crimson, segments: 32));
374	        _ball.Set(draw);
375	        _ball.Set<VisibleComponent>();
376	
377	        // Clickable hit-area for the ball — child entity offset to the ball's
378	        // top-left so the bounds-based hit test wraps the circle. Clicking the
379	        // ball switches to follow mode.
380	        var hitArea = _world.CreateEntity();
381	        hitArea.Set(new TransformComponent(new Vector2(-BallRadius, -BallRadius)));
382	        hitArea.SetParent(_ball);
383	        hitArea.Set(new SimpleButtonComponent
384	        {
385	            Size = new Vector2(BallRadius * 2, BallRadius * 2),
386	            LineThickness = 0f,
387	            Color = Color.Transparent,
388	            FillColor = Color.Transparent,
389	            TextEntity = null,
390	            Target = RenderTargetID.Main,
391	        });
392	        hitArea.Set(new DemoButtonComponent
393	        {
394	            Id = "mode.follow",
395	            DefaultColor = Color.Transparent,
396	            HoveredColor = Color.Transparent,
397	            ActiveColor = Color.Transparent,
398	        });
399	        hitArea.Set<VisibleComponent>();
400	    }
401	
402	    /// Green cross marking where the camera *wants* to be. Parented to whichever
403	    /// entity currently has <see cref="CameraFollowTargetComponent"/> so it sits
404	    /// exactly at the target — when the camera lerps, the green cross stays put
405	    /// and the screen-center yellow cross drifts toward it.
406	    private void CreateTargetCross()
407	    {
408	        _targetCross = _world.CreateEntity();
409	        _targetCross.Set(new TransformComponent(Vector2.Zero));
410	        // 0.98 puts the cross above the ball (0.97) so the target marker is
411	        // never occluded when it sits on the ball in follow mode.
412	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.98f };
413	        draw.SetMeshData(CrossMesh(armPixels: 16, thicknessPixels: 3, color: Color.Black));
414	        _targetCross.Set(draw);
415	        _targetCross.Set<VisibleComponent>();
416	    }
417	
418	    /// Yellow cross drawn on HUD at the screen center — marks the point the
419	    /// camera is currently looking at. Camera-independent (HUD is not affected
420	    /// by the view transform), so this stays put even as the world scrolls.
421	    private void CreateCameraCenterCross()
422	    {
423	        var entity = _world.CreateEntity();
424	        entity.Set(new TransformComponent(new Vector2(
425	            _viewportManager.VirtualWidth / 2f,
426	            _viewportManager.VirtualHeight / 2f)));
427	        var draw = new DrawComponent { Target = RenderTargetID.HUD, LayerDepth = 0.92f };
428	        draw.SetMeshData(CrossMesh(armPixels: 14, thicknessPixels: 3, color: Color.White));
429	        entity.Set(draw);
430	        entity.Set<VisibleComponent>();
431	    }
432	
433	    private static CompositeMeshGenerator CrossMesh(int armPixels, int thicknessPixels, Color color)
434	    {
435	        var halfT = thicknessPixels / 2;
436	        return new CompositeMeshGenerator()
437	            .Add(new FilledRectangleMeshGenerator(
438	                new Rectangle(-armPixels, -halfT, armPixels * 2, thicknessPixels), color))
439	            .Add(new FilledRectangleMeshGenerator(
440	                new Rectangle(-halfT, -armPixels, thicknessPixels, armPixels * 2), color));
441	    }
