445	    private void BuildHud(ContentManager content)
446	    {
447	        var squareButtons = content.Load<Texture2D>("SproutLands/Buttons/square_26x26");
448	        var settingsSheet = content.Load<Texture2D>("SproutLands/Buttons/settings_buttons");
449	
450	        DemoHeader.Build(
451	            _world, _viewportManager, _font, squareButtons,
452	            title: "camera",
453	            descriptionLines: new[]
454	            {
455	                "Use keyboard keys 0 to 5 to switch the camera target",
456	                "and the L key to toggle camera lerp.",
457	                "Use the WASD keys to control the red dot.",
458	            });
459	
460	        BuildSidebar(squareButtons, settingsSheet);
461	    }
462	
463	    private void BuildSidebar(Texture2D squareButtons, Texture2D settingsSheet)
464	    {
465	        var capStyle = new KeyCapStyle
466	        {
467	            SpriteSheet = squareButtons,
468	            DefaultSource = SproutSquareButtons.CreamLight,
469	            HoverSource   = SproutSquareButtons.CreamDark,
470	            ActiveSource  = SproutSquareButtons.TanDark,
471	            // 42 matches the lerp toggle pill width so all sidebar elements
472	            // line up on a shared left edge.
473	            CapPixels = 42,
474	            CapLabelScale = 0.22f,
475	            CapLabelColor = SproutPalette.WarmBrown,
476	        };
477	        var rowStyle = new KeyRowStyle
478	        {
479	            LabelColor = SproutPalette.TextLight,
480	            HoverColor = SproutPalette.TextHover,
481	            ActiveColor = SproutPalette.TextSelected,
482	            LabelScale = 0.18f,
483	            Gap = 10f,
484	            BackgroundColor = SproutPalette.DarkBgSecondary,
485	            HoverBackgroundColor = SproutPalette.DarkBgSecondary,
486	            ActiveBackgroundColor = SproutPalette.DarkBgSecondary,
487	            BackgroundPaddingX = 10f,
488	            BackgroundPaddingY = 6f,
489	        };
490	
491	        (Entity Container, Entity Outline, Vector2 Size) Row(string id, string key, string label) =>
492	            _world.CreateKeyRow(id, key, label, _font, capStyle, rowStyle, layerDepth: 0.96f);
493	
494	        // Order: 0 follow, 1 TL, 2 TR, 3 BR, 4 BL, 5 center.
495	        var follow = Row("mode.follow", "0", "follow red dot");
496	        var tl     = Row("mode.tl",     "1", "top-left");
497	        var tr     = Row("mode.tr",     "2", "top-right");
498	        var br     = Row("mode.br",     "3", "bottom-right");
499	        var bl     = Row("mode.bl",     "4", "bottom-left");
500	        var center = Row("mode.center", "5", "center");
501	
502	        // Toggle pill native is 28x18 (aspect ~1.56). Draw at 42x27 = native × 1.5
503	        // so the aspect ratio is preserved and the pill scales to match the cap chip.
504	        var lerp = _world.CreateToggleRow(
505	            id: "toggle.lerp",
506	            rowLabel: "smooth lerp",
507	            font: _font,
508	            toggleSheet: settingsSheet,
509	            offSource: SproutSettings.ToggleOff,
510	            onSource: SproutSettings.ToggleOn,
511	            initiallyOn: _lerpSmooth,
512	            toggleSize: new Vector2(42, 27),
513	            row: rowStyle,
514	            layerDepth: 0.96f);
515	
516	        _sidebarButtons[Mode.Follow]      = follow.Outline;
517	        _sidebarButtons[Mode.FixedTL]     = tl.Outline;
518	        _sidebarButtons[Mode.FixedTR]     = tr.Outline;
519	        _sidebarButtons[Mode.FixedBR]     = br.Outline;
520	        _sidebarButtons[Mode.FixedBL]     = bl.Outline;
521	        _sidebarButtons[Mode.FixedCenter] = center.Outline;
522	        _lerpToggle = lerp.Outline;
523	
524	        const float rowGap = 6f;       // gap BETWEEN per-row backgrounds
525	        const float groupGap = 16f;    // larger gap before the lerp toggle group
526	
527	        new AutoLayoutBuilder(_world, _viewportManager)
528	            .CreateRoot(ScreenAnchor.TopLeft, RenderTargetID.HUD)
529	            .Direction(LayoutDirection.Vertical)
530	            .Gap(rowGap)
531	            // Screen-root stacks roots vertically, so the sidebar already lands
532	            // below the header automatically — just add a small breathing pad.
533	            .Padding(20 /* top */, 12 /* right */, 12 /* bottom */, 12 /* left */)
534	            .AlignCross(CrossAxisAlignment.Start)
535	            .AddSlot(slot => slot.Attach(follow.Container).MeasureWith(_ => follow.Size))
536	            .AddSlot(slot => slot.Attach(tl.Container).MeasureWith(_ => tl.Size))
537	            .AddSlot(slot => slot.Attach(tr.Container).MeasureWith(_ => tr.Size))
538	            .AddSlot(slot => slot.Attach(br.Container).MeasureWith(_ => br.Size))
539	            .AddSlot(slot => slot.Attach(bl.Container).MeasureWith(_ => bl.Size))
540	            .AddSlot(slot => slot.Attach(center.Container).MeasureWith(_ => center.Size))
541	            .AddSlot(slot => slot.Attach(_world.CreateEntity()).MeasureWith(_ => new Vector2(0, groupGap - rowGap)))
542	            .AddSlot(slot => slot.Attach(lerp.Container).MeasureWith(_ => lerp.Size))
543	            .Build();
544	    }
