546	    // ─── pipeline ────────────────────────────────────────────────────────────
547	
548	    private SequentialSystem<GameState> CreateUpdateSystem()
549	    {
550	        return new SequentialSystem<GameState>(
551	            new CursorInputSystem(_world),
552	            new IntrinsicSizingSystem(_world),
553	            new AutoLayoutSystem(_world, _viewportManager),
554	            new DemoButtonInteractionSystem(_world),
555	            new DemoIconRecolorSystem(_world),
556	            new ToggleSwitchSystem(_world),
557	            new PlayerBallMovementSystem(_world, BoundaryHalfWidth, BoundaryHalfHeight, BallRadius, MoveSpeed),
558	            new CameraDemoInputSystem(this),
559	            new CameraFollowSystem(_world, _camera),
560	            new HierarchySystem(_world),
561	            new CursorPositionSystem(_world, _camera, _viewportManager),
562	            new CursorDrawPrepSystem(_world));
563	    }
564	
565	    private SequentialSystem<GameState> CreateDrawSystem()
566	    {
567	        return new SequentialSystem<GameState>(
568	            new SpritePrepSystem(_world, _graphicsDevice, pixelPerfectRendering: false),
569	            new TextPrepSystem(_world, pixelPerfectRendering: false),
570	            new MeshPrepSystem(_world),
571	            new ButtonMeshPrepSystem(_world),
572	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _camera, _renderTargets, _world),
573	            new FinalDrawSystem(_spriteBatch, _graphicsDevice, _viewportManager, _camera, _renderTargets));
574	    }
575	
576	    public void Dispose()
577	    {
578	        UpdateSystem.Dispose();
579	        DrawSystem.Dispose();
580	        foreach (var rt in _renderTargets.Values) rt.Dispose();
581	        _world.Dispose();
582	        GC.SuppressFinalize(this);
583	    }
584	}
585	
586	/// Tag identifying the player-controlled circle in the camera demo.
587	public struct PlayerBallTag { }
588	
589	/// Reads keyboard input (WASD + arrows) and translates the tagged player entity,
590	/// clamping its position so the ball stays inside the boundary rectangle.
591	[With(typeof(PlayerBallTag), typeof(TransformComponent))]
592	public class PlayerBallMovementSystem : AEntitySetSystem<GameState>
593	{
594	    private readonly float _halfWidth;
595	    private readonly float _halfHeight;
596	    private readonly float _radius;
597	    private readonly float _speed;
598	
599	    public PlayerBallMovementSystem(World world, float halfWidth, float halfHeight, float radius, float speed)
600	        : base(world)
601	    {
602	        _halfWidth = halfWidth;
603	        _halfHeight = halfHeight;
604	        _radius = radius;
605	        _speed = speed;
606	    }
607	
608	    protected override void Update(GameState state, in Entity entity)
609	    {
610	        var keyboard = Keyboard.GetState();
611	        var dir = Vector2.Zero;
612	        if (keyboard.IsKeyDown(Keys.A) || keyboard.IsKeyDown(Keys.Left))  dir.X -= 1f;
613	        if (keyboard.IsKeyDown(Keys.D) || keyboard.IsKeyDown(Keys.Right)) dir.X += 1f;
614	        if (keyboard.IsKeyDown(Keys.W) || keyboard.IsKeyDown(Keys.Up))    dir.Y -= 1f;
615	        if (keyboard.IsKeyDown(Keys.S) || keyboard.IsKeyDown(Keys.Down))  dir.Y += 1f;
616	        if (dir != Vector2.Zero) dir.Normalize();
617	
618	        var transform = entity.Get<TransformComponent>();
619	        var next = transform.Position + dir * _speed * state.Time;
620	        next.X = MathHelper.Clamp(next.X, -_halfWidth + _radius, _halfWidth - _radius);
621	        next.Y = MathHelper.Clamp(next.Y, -_halfHeight + _radius, _halfHeight - _radius);
622	        transform.Position = next;
623	    }
624	}
625	
626	/// Polls the keyboard for camera-mode shortcuts (0–5, L) and forwards them
627	/// to the owning <see cref="CameraDemoScreen"/>. Edge-triggered: each key press
628	/// fires once per release-then-press cycle.
629	public class CameraDemoInputSystem : ISystem<GameState>
630	{
631	    private readonly CameraDemoScreen _screen;
632	    private KeyboardState _previous;
633	    public bool IsEnabled { get; set; } = true;
634	
635	    public CameraDemoInputSystem(CameraDemoScreen screen)
636	    {
637	        _screen = screen;
638	        _previous = Keyboard.GetState();
639	    }
640	
641	    public void Update(GameState state)
642	    {
643	        if (!IsEnabled) return;
644	        var current = Keyboard.GetState();
645	        bool Pressed(Keys k) => current.IsKeyDown(k) && !_previous.IsKeyDown(k);
646	
647	        if (Pressed(Keys.D0) || Pressed(Keys.NumPad0)) _screen.SetMode(CameraDemoScreen.Mode.Follow);
648	        if (Pressed(Keys.D1) || Pressed(Keys.NumPad1)) _screen.SetMode(CameraDemoScreen.Mode.FixedTL);
649	        if (Pressed(Keys.D2) || Pressed(Keys.NumPad2)) _screen.SetMode(CameraDemoScreen.Mode.FixedTR);
650	        if (Pressed(Keys.D3) || Pressed(Keys.NumPad3)) _screen.SetMode(CameraDemoScreen.Mode.FixedBR);
651	        if (Pressed(Keys.D4) || Pressed(Keys.NumPad4)) _screen.SetMode(CameraDemoScreen.Mode.FixedBL);
652	        if (Pressed(Keys.D5) || Pressed(Keys.NumPad5)) _screen.SetMode(CameraDemoScreen.Mode.FixedCenter);
653	        if (Pressed(Keys.L)) _screen.ToggleLerp();
654	        if (Pressed(Keys.Escape)) _screen.GoBackToLauncher();
655	
656	        _previous = current;
657	    }
658	
659	    public void Dispose() => GC.SuppressFinalize(this);
660	}
