/// While the red dot is the active camera target (follow mode), zooms the camera
/// out a little in proportion to how far its center lags behind the dot. The lag
/// is the world-space distance between the ball and the resolved camera position;
/// it grows when the dot moves faster than the camera can ease toward it, and when
/// the dot pushes past the camera-bounds edges (where the clamp pins the camera).
///
/// Lag maps linearly to a zoom reduction, capped at <see cref="MaxZoomOut"/>, and
/// the applied zoom is eased toward that target so it widens and recovers smoothly.
/// When no ball is the active target (fixed modes), the target zoom is 1, so the
/// view eases back to its default. This only writes <c>Camera.Zoom</c>, so it never
/// competes with <see cref="CameraFollowSystem"/>'s ownership of <c>Camera.Position</c>.
public class CameraLagZoomSystem : ISystem<GameState>
{
    // Lag (in world units) at which the zoom-out reaches its full MaxZoomOut. Sized
    // for this demo's boundary/camera-bounds geometry — at a corner the clamp holds
    // the camera ~110px behind the dot, comfortably inside this ceiling.
    private const float MaxLag = 150f;
    // Largest zoom reduction; 0.18 means the camera widens to at most 0.82× — "a little".
    private const float MaxZoomOut = 0.18f;
    // Exponential easing rate for the applied zoom, matched to the smooth-lerp feel.
    private const float ZoomDamping = 6f;

    private readonly MonoDreams.Component.Camera _camera;
    private readonly EntitySet _activeBallTargets;
    private float _currentZoom = 1f;

    public bool IsEnabled { get; set; } = true;

    public CameraLagZoomSystem(World world, MonoDreams.Component.Camera camera)
    {
        _camera = camera;
        // The ball only carries CameraFollowTargetComponent while in follow mode, so
        // this set is non-empty exactly when the dot is the camera target.
        _activeBallTargets = world.GetEntities()
            .With<PlayerBallTag>()
            .With<CameraFollowTargetComponent>()
            .With<TransformComponent>()
            .AsSet();
    }

    public void Update(GameState state)
    {
        if (!IsEnabled) return;

        var targetZoom = 1f;
        foreach (var entity in _activeBallTargets.GetEntities())
        {
            if (!entity.Get<CameraFollowTargetComponent>().IsActive) continue;
            var lag = (entity.Get<TransformComponent>().Position - _camera.Position).Length();
            var t = MathHelper.Clamp(lag / MaxLag, 0f, 1f);
            targetZoom = 1f - t * MaxZoomOut;
            break;
        }

        var smooth = 1f - (float)Math.Exp(-ZoomDamping * state.Time);
        _currentZoom = MathHelper.Lerp(_currentZoom, targetZoom, smooth);
        _camera.Zoom = _currentZoom;
    }

    public void Dispose()
    {
        _activeBallTargets.Dispose();
        GC.SuppressFinalize(this);
    }
}

